 LaunchedEffect(Unit){while(true){CongregationTimer.refresh();FoldbackTimer.refresh();if(castBridge.hasActiveSession())castBridge.publish(live,presentation.live.black,liveTheme,textSize,autoFit);if(live?.kind=="countdown")wiredBridge.render(CongregationTimer.slide(),presentation.live.black);delay(if(live?.kind=="countdown"||castBridge.assignedBus()==PresentationBus.FOLDBACK||wiredBridge.assignedBus()==PresentationBus.FOLDBACK)500 else 1500)}}
