@Composable fun MediaPanel(onPreview:(PresentationSlide)->Unit,onGoLive:(PresentationSlide)->Unit){var mode by rememberSaveable{mutableStateOf("Lyrics")};PageHeading("Media","Lyrics and countdown.");Row(Modifier.fillMaxWidth(),horizontalArrangement=Arrangement.spacedBy(8.dp)){listOf("Lyrics","Timer").forEach{item->if(mode==item)Button({mode=item},Modifier.weight(1f)){Text(item)}else OutlinedButton({mode=item},Modifier.weight(1f)){Text(item)}}};if(mode=="Lyrics")LyricsEditor(onPreview,onGoLive)else TimerEditor(onPreview,onGoLive)}
@Composable private fun LyricsEditor(onPreview:(PresentationSlide)->Unit,onGoLive:(PresentationSlide)->Unit){var text by rememberSaveable{mutableStateOf("")};fun slide()=PresentationSlide(text=text.lines().take(4).joinToString("\n"),kind="lyrics");SectionCard{OutlinedTextField(text,{text=it},Modifier.fillMaxWidth().height(220.dp),label={Text("Lyrics")});Row(Modifier.fillMaxWidth(),horizontalArrangement=Arrangement.spacedBy(8.dp)){OutlinedButton({if(text.isNotBlank())onPreview(slide())},Modifier.weight(1f)){Text("PREVIEW")};Button({if(text.isNotBlank()){val s=slide();onPreview(s);onGoLive(s)}},Modifier.weight(1f)){Text("GO LIVE")}}}}
